CREATE VIEW std_inventory_curated AS SELECT CASE  WHEN (((game_title = 'Grand Theft Auto VI') AND (platform_name = 'PS5'))) THEN (NULL) ELSE igdb_id END AS igdb_id, CASE  WHEN (((game_title = 'Grand Theft Auto VI') AND (platform_name = 'PS5'))) THEN (NULL) ELSE opencritic_id END AS opencritic_id, game_title, genre_raw, theme_raw, mode_raw, perspective_raw, acquisition_source_raw, storage_location_raw, organization_folder_raw, play_status_raw, CASE  WHEN (((game_title = 'Grand Theft Auto VI') AND (platform_name = 'PS5'))) THEN (CAST('f' AS BOOLEAN)) ELSE owned_flag END AS owned_flag, difficulty_rating, base_length_hours, full_completion_hours, file_size_gb, platform_name, acquisition_source, play_status, CASE  WHEN (((game_title = 'Grand Theft Auto VI') AND (platform_name = 'PS5'))) THEN ('Unknown') ELSE access_status END AS access_status, CASE  WHEN (((game_title = 'Grand Theft Auto VI') AND (platform_name = 'PS5'))) THEN (NULL) ELSE storage_location END AS storage_location, CASE  WHEN (((game_title = 'Grand Theft Auto VI') AND (platform_name = 'PS5'))) THEN (CAST('2026-11-19' AS DATE)) WHEN ((platform_name = 'PS5')) THEN ((SELECT max("Release Date") FROM stg_ps5_inventory AS p WHERE (main."trim"(p.Title) = game_title))) ELSE NULL END AS release_date, duplicate_rank, duplicate_count FROM std_inventory_resolved;
